SELECT i.invoice_no, i.invoice_date, i.customer_id, i.country, i.amount, i.customer_type
FROM invoices i WHERE i.invoice_type='return' AND i.invoice_date >= '2010-03-01' AND i.invoice_date < '2010-04-01'
ORDER BY i.amount DESC LIMIT 10;

SELECT 100.0*(SELECT SUM(amount) FROM invoices WHERE invoice_type='return' AND invoice_date >= '2010-03-01' AND invoice_date < '2010-04-01' AND customer_id IS NOT NULL AND customer_id<>14301)/(SELECT SUM(amount) FROM invoices WHERE invoice_type='sale' AND invoice_date >= '2010-03-01' AND invoice_date < '2010-04-01') AS mar_rate_ex_14301,
100.0*(SELECT SUM(amount) FROM invoices WHERE invoice_type='return' AND invoice_date >= '2010-03-01' AND invoice_date < '2010-04-01' AND customer_id=14301)/(SELECT SUM(amount) FROM invoices WHERE invoice_type='sale' AND invoice_date >= '2010-03-01' AND invoice_date < '2010-04-01') AS rate_from_14301,
100.0*12575.44/537893.54 AS feb_rate, 100.0*31900.65/761665.62 AS mar_rate;

SELECT i.customer_type, SUM(CASE WHEN substr(i.invoice_date,1,7)='2010-07' THEN i.amount ELSE 0 END) AS base_gmv, SUM(CASE WHEN substr(i.invoice_date,1,7)='2011-07' THEN i.amount ELSE 0 END) AS cur_gmv,
 SUM(CASE WHEN substr(i.invoice_date,1,7)='2011-07' THEN i.amount ELSE 0 END)-SUM(CASE WHEN substr(i.invoice_date,1,7)='2010-07' THEN i.amount ELSE 0 END) AS delta
FROM invoices i WHERE i.invoice_type='sale' AND substr(i.invoice_date,1,7) IN ('2010-07','2011-07') GROUP BY i.customer_type;

SELECT i.country, SUM(CASE WHEN substr(i.invoice_date,1,7)='2010-07' THEN i.amount ELSE 0 END) AS base_gmv, SUM(CASE WHEN substr(i.invoice_date,1,7)='2011-07' THEN i.amount ELSE 0 END) AS cur_gmv,
 SUM(CASE WHEN substr(i.invoice_date,1,7)='2011-07' THEN i.amount ELSE 0 END)-SUM(CASE WHEN substr(i.invoice_date,1,7)='2010-07' THEN i.amount ELSE 0 END) AS delta
FROM invoices i WHERE i.invoice_type='sale' AND substr(i.invoice_date,1,7) IN ('2010-07','2011-07') GROUP BY i.country ORDER BY delta DESC LIMIT 8;

SELECT l.category, SUM(CASE WHEN substr(i.invoice_date,1,7)='2011-07' THEN l.amount ELSE 0 END) - SUM(CASE WHEN substr(i.invoice_date,1,7)='2010-07' THEN l.amount ELSE 0 END) AS delta
FROM invoice_lines l JOIN invoices i ON i.invoice_no=l.invoice_no
WHERE i.invoice_type='sale' AND i.customer_id IS NULL AND substr(i.invoice_date,1,7) IN ('2010-07','2011-07') GROUP BY l.category ORDER BY delta DESC;
